window.RP_SESSION={"id":"S-f7188c05d1b3","messages":[{"id":"RP-0110038","time":"2026-04-12T16:17:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":" ··· 마리우스가 느지막이 눈을 떴을 때, 이미 션은 방을 떠난 후였다. 눈을 비비고 천천히 몸을 일으키자, 잘못됨을 확실히 느꼈다.\n\n몸이 꽤 무겁고, 목이 아프다. 머리가 아릿한 것도 물론이고. 옅은 소리 내며 옷 갖춰입고, 길드로 내려갔다. 포션을 사 마셔야 하나···.\n\n시장으로 나가 포션을 살지 고민하기 시작했다.","characters":["P-b6d81d634c6e"]},{"id":"RP-0110039","time":"2026-04-12T16:18:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"옮길까 두려워, 오래간만에 대장간에서 직접 고쳐냈던 투구를 썼다.","characters":["P-b6d81d634c6e"]},{"id":"RP-0110040","time":"2026-04-12T16:19:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ ··· 아. ”\n\n살짝 눈 앞이 흐릿해서, 별 수 없이 길드 회관 의자에 잠시 앉았다.","characters":["P-b6d81d634c6e"]},{"id":"RP-0110041","time":"2026-04-12T16:21:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"······ 에휴, 벽에 투구를 대고 좀 나아질때까지 이렇게 있기로 결정했다. 다른 사람들이 보면 고민하는 사람처럼 보이겠지.","characters":["P-b6d81d634c6e"]},{"id":"RP-0110042","time":"2026-04-12T16:41:00+09:00","room":"RP","name":"루체","profile":"루체","identity":"reviewed","type":"dialogue","body":"\"투구다\"","characters":["P-d8e7afee7c51"]},{"id":"RP-0110043","time":"2026-04-12T16:42:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 루체, 씨? ”\n\n뭐, 뭐야? 목소리 듣고 단번에 알아차린 듯 벌떡 일어났다.","characters":["P-b6d81d634c6e"]},{"id":"RP-0110044","time":"2026-04-12T16:42:00+09:00","room":"RP","name":"루체","profile":"루체","identity":"reviewed","type":"dialogue","body":"\"왜 투구 쓰고 있어요?\"","characters":["P-d8e7afee7c51"]},{"id":"RP-0110045","time":"2026-04-12T16:44:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 아, 제가···. 몸이 안 좋아져서. 혹시나 옮길까봐요. ”","characters":["P-b6d81d634c6e"]},{"id":"RP-0110046","time":"2026-04-12T16:44:00+09:00","room":"RP","name":"루체","profile":"루체","identity":"reviewed","type":"dialogue","body":"\"감기 걸렸어요?\"","characters":["P-d8e7afee7c51"]},{"id":"RP-0110047","time":"2026-04-12T16:45:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"콜록, 짧은 기침 소리와 함께 고개를 끄덕였다.","characters":["P-b6d81d634c6e"]},{"id":"RP-0110048","time":"2026-04-12T16:45:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 그런가봐요. ”","characters":["P-b6d81d634c6e"]},{"id":"RP-0110049","time":"2026-04-12T16:45:00+09:00","room":"RP","name":"루체","profile":"루체","identity":"reviewed","type":"dialogue","body":"\"감기약, 가져다 줄게요\"","characters":["P-d8e7afee7c51"]},{"id":"RP-0110050","time":"2026-04-12T16:45:00+09:00","room":"RP","name":"루체","profile":"루체","identity":"reviewed","type":"dialogue","body":"총총총 길드 지하로 사라집니다","characters":["P-d8e7afee7c51"]},{"id":"RP-0110051","time":"2026-04-12T16:47:00+09:00","room":"RP","name":"루체","profile":"루체","identity":"reviewed","type":"dialogue","body":"이내 몇분 후 올라온 루체의 손엔 라르손 특제 감기약포션이 쥐어져 있었습니다","characters":["P-d8e7afee7c51"]},{"id":"RP-0110052","time":"2026-04-12T16:47:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"그런 게 있었어?","characters":["P-b6d81d634c6e"]},{"id":"RP-0110053","time":"2026-04-12T16:47:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"아**","characters":["P-b6d81d634c6e"]},{"id":"RP-0110054","time":"2026-04-12T16:47:00+09:00","room":"RP","name":"루체","profile":"루체","identity":"reviewed","type":"dialogue","body":"약제사가 있으니... 만들어 달라 카면 되지...","characters":["P-d8e7afee7c51"]},{"id":"RP-0110055","time":"2026-04-12T16:49:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"어···. 포션 바라보고, 맞다. 라르손 씨가 있었지. 하며 받아듭니다.\n\n“ 고마워요. ”","characters":["P-b6d81d634c6e"]},{"id":"RP-0110056","time":"2026-04-12T16:51:00+09:00","room":"RP","name":"루체","profile":"루체","identity":"reviewed","type":"dialogue","body":"\"별말씀을요\"","characters":["P-d8e7afee7c51"]},{"id":"RP-0110057","time":"2026-04-12T16:52:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"투구 벗고서 포션 들이킵니다. 좀 자야겠어, 루체에게 가벼운 인사 건네고 터덜터덜 기숙사로 돌아갑니다.","characters":["P-b6d81d634c6e"]}]};
